python3 -c "
import json
from collections import defaultdict
g=json.load(open('graphify-out/graph.json'))
nodes={n['id']:n for n in g['nodes']}

def internal(nid):
    n=nodes.get(nid); 
    return bool(n) and str(n.get('source_file','')).startswith('internal/')

for rels in (('calls',), ('calls','indirect_call','method')):
    callers=defaultdict(set)
    for l in g['links']:
        if l.get('relation') in rels:
            t=l['target']
            if internal(t):
                callers[t].add(l['source'])
    top=sorted(callers.items(), key=lambda kv:-len(kv[1]))[:12]
    print('=== relations', rels, '===')
    for tid,cs in top:
        n=nodes[tid]
        print(f\"{len(cs):4d}  {n.get('label')}  [{n.get('source_file')}:{n.get('source_location')}]  id={tid}\")
    print()
"

