g=json.load(open('graphify-out/graph.json'))
nodes={n['id']:n for n in g['nodes']}
srcfiles=Counter()
for l in g['links']:
    if l.get('relation')=='calls' and l['target']=='version_sortversion_len':
        srcfiles[nodes[l['source']].get('source_file')]+=1
print('distinct caller source files:', len(srcfiles))
for f,c in srcfiles.most_common(15):
    print(c,f)
"

